    function getInput3() {
        text = $("#input").value;
        if (text.match(/\&\&|::/g)) {
            text = text.replace(/\&\&/g, '\n');
            list = text.match(/.*::.*/g);
            html = [];
            for (i = 0; i < list.length; i++) {
                l = list[i].match(/(.*)::(.*)/);
                title = l[1];
                url = l[2]
                html.push({
                    title: title,
                    url: url
                })
            }
            $("#input").value = JSON.stringify(html)
        } else {
            html = "";
            json = eval(text);
            for (i in json) {
                html += json[i].title + "::" + json[i].url + "\n"
            }
            $("#input").value = html
        }
